// Slug 把 name 转成 URL 友好的 slug：小写、空白折成单个连字符、首尾不留。
func Slug(name string) string {
	fields := strings.Fields(name)
	for i, field := range fields {
		fields[i] = strings.ToLower(field)
	}
	return strings.Join(fields, "-")
}
